def derive(root, src, dst, have, hs, want):
    p = os.path.join(root, src); q = os.path.join(root, dst)
    if not os.path.isfile(p): fail('MISS: no file ' + p)
    s = open(p).read()
    if md5(s) != have: fail('%s: md5 %s, not gl28\'s %s' % (p, md5(s), have))
    if q != p and os.path.exists(q): fail(q + ' exists already')
