for rel, have, hs, want in TREE_MOD:
    p, s = derive(tree, rel, rel, have, hs, want); plan.append((p, s, None))
if main:
    for src, dst, have, hs, want in MAIN_DERIVE:
        p, s = derive(main, src, dst, have, hs, want)
        bak = p + '.gl28bak' if src == dst else None
        if bak and os.path.exists(bak): fail(bak + ' exists already')
        plan.append((p, s, bak))
for p, s, bak in plan:   # every check passed: now write
    if bak: open(bak, 'w').write(open(p).read())
    open(p, 'w').write(s)
    print('gl29_apply: wrote %s (md5 %s)%s' % (p, md5(s), ' (original saved as %s)' % bak if bak else ''))
print('gl29_apply: OK, %d files' % len(plan))
